import type { Book } from "@/types/book";

/**
 * A synthetic catalog that looks like Open Library output: crowd-edited subject headings,
 * uneven metadata, popular and obscure titles, series volumes, several books per author.
 * Nothing here is fetched; it exists so the engine can be tested without the network.
 */

interface Spec {
  id: string;
  title: string;
  author: string;
  subjects: string[];
  pages?: number;
  year?: number;
  rating?: number;
  ratings?: number;
  readers?: number;
  description?: string;
  noCover?: boolean;
}

function book(s: Spec): Book {
  return {
    id: s.id,
    title: s.title,
    authors: [s.author],
    subjects: s.subjects,
    categories: [],
    description: s.description,
    coverUrl: s.noCover ? undefined : `https://covers.openlibrary.org/b/id/${s.id.replace(/\D/g, "")}-M.jpg`,
    publishedYear: s.year,
    pageCount: s.pages,
    isbn: `978${s.id.replace(/\D/g, "").padStart(10, "0")}`,
    rating: s.rating !== undefined ? { average: s.rating, count: s.ratings ?? 50 } : undefined,
    readerCount: s.readers,
    source: "openlibrary",
    sourceId: s.id,
  };
}

